const ASIRGARH_DATA={overview:{title:"Asirgarh Fort Explorer",nativeTitle:"असीरगढ़ किला • Kili-i-Dakkan",subtitle:"The Impregnable Gateway to the Deccan in the Satpura Range",location:"Burhanpur District, Madhya Pradesh, India",coordinates:"21.4699° N, 76.2952° E",elevation:"750 m (2,460 ft) above sea level",cliffHeight:"230 m above surrounding Satpura plain",builtEra:"14th Century CE",founders:"Asa Ahir (Ahir Chieftain), Faruqui Dynasty, Mughal Empire",architecturalStyle:"Indo-Islamic, Maratha Military & Hill-Fort Architecture",area:"Over 60 Acres across 3 Citadels",nickname:"Gateway to the Deccan (दक्कन का दरवाजा / Key to Southern India)",summary:"Perched atop a sheer basalt outcrop in the Satpura Mountain Range, Asirgarh Fort commands the strategic Burhanpur Gap—the historic land pass connecting Northern India to the Deccan Plateau. For centuries, controlling Asirgarh meant holding the key to southern conquest."},quickStats:[{label:"Elevation",value:"750 m",icon:"⛰️",subtext:"Above sea level"},{label:"Strategic Gap",value:"Burhanpur",icon:"🗺️",subtext:"North-South Trade Pass"},{label:"Citadels",value:"3 Forts",icon:"🏰",subtext:"Asirgarh, Kamargarh, Malaygarh"},{label:"Akbar's Siege",value:"1600–1601",icon:"⚔️",subtext:"Final Akbar Conquest"}],historyTimeline:[{year:"14th Century (c. 1380 CE)",title:"Foundation by Asa Ahir",era:"Ahir Chieftaincy",description:"Asa Ahir, a prosperous chieftain and leader of the local Ahir community, constructs a mud-and-stone stronghold atop the hill to protect thousands of cattle and villagers from bandits and raiders."},{year:"1399 CE",title:"Faruqui Dynasty Acquisition & Fortification",era:"Khandesh Sultanate",description:"Nasir Khan Faruqui, the ruler of Khandesh, seizes the fort from Asa Ahir through stratagem. The Faruqui kings transform the hill into a massive stone fortress, naming it Asirgarh in honor of Asa Ahir."},{year:"1588 CE",title:"Construction of Grand Jama Masjid",era:"Faruqui Reign",description:"Adil Shah Faruqui orders the construction of the magnificent Jama Masjid inside the fort, featuring twin 80-foot minarets and bilingual inscriptions in Sanskrit and Arabic."},{year:"1600–1601 CE",title:"Akbar's 7-Month Siege & Conquest",era:"Mughal Empire",description:"Mughal Emperor Akbar personally leads a 7-month siege against Bahadur Shah Faruqui. Finding the sheer cliffs unassailable, Akbar secures the fort's surrender through gold diplomacy, bribery, and negotiation. It marks Akbar's final military conquest."},{year:"17th–18th Century",title:"Mughal Command Post for Deccan Wars",era:"Mughal Empire",description:"Asirgarh serves as the primary forward military supply base for Mughal campaigns in Southern India under Shah Jahan and Aurangzeb, earning the Persian title 'Kili-i-Dakkan' (Key to the Deccan)."},{year:"1760 CE",title:"Maratha Takeover",era:"Maratha Empire",description:"Following the decline of Mughal power, the Marathas take possession of Asirgarh Fort, integrating it into the defensive grid of the Peshwas and later the Scindias of Gwalior."},{year:"1819 CE",title:"Third Anglo-Maratha War & British Annexation",era:"British East India Company",description:"British forces commanded by Brigadier-General John Doveton and Sir John Malcolm lay siege to Asirgarh. After a 20-day intense artillery bombardment, the Scindia garrison surrenders, bringing the fort under British rule."}],builders:[{name:"Asa Ahir",role:"Founder & Initial Builder",era:"Late 14th Century",icon:"👑",dynasty:"Ahir Chieftaincy",description:"A legendary local chieftain who built the initial earthen fort walls to safeguard his vast cattle herds and community. His legacy lives on in the name 'Asirgarh' (Fort of Asa)."},{name:"Nasir Khan Faruqui",role:"Stone Fortifier & Sultan",era:"1399 – 1437 CE",icon:"🏰",dynasty:"Faruqui Dynasty of Khandesh",description:"Turned the hill stronghold into an unassailable stone citadel, constructing thick ramparts, deep water tanks, and defensive gateways overlooking the Satpura pass."},{name:"Emperor Akbar",role:"Conqueror & Mughal Imperial Patron",era:"1556 – 1605 CE",icon:"⚔️",dynasty:"Mughal Dynasty",description:"Captured Asirgarh in 1601 CE after a legendary 7-month siege. Expanded imperial garrisons, added Mughal palaces, and installed victory inscriptions commemorating his final military triumph."},{name:"Scindias of Gwalior",role:"Maratha Custodians",era:"18th – 19th Century",icon:"🛡️",dynasty:"Maratha Confederacy",description:"Maintained Asirgarh as a formidable frontier fort guarding Maratha territories against invading British and Nizam forces until its fall in 1819."}],strategicImportance:{title:"The Gateway to the Deccan",subtitle:"Why Asirgarh Was the Most Coveted Fortress in Central India",points:[{title:"The Burhanpur Gap (Asa Pass)",icon:"🏔️",detail:"The Satpura Range forms an almost impenetrable mountain wall across Central India. The only broad natural gap lies at Burhanpur. Asirgarh sits directly above this gap, controlling all movement between North and South."},{title:"Control of Trade & Military Routes",icon:"🛣️",detail:"Caravans carrying spices, textiles, silk, and gold, as well as marching imperial armies, were forced to pass under the guns of Asirgarh. No empire could safely invade the Deccan without securing this fort."},{title:"Impregnable Natural Defenses",icon:"🧗",detail:"Perched on a sheer cliff rising 230 meters above the plain, the fort features perpendicular rock faces on all sides, making scaling ladders or direct assaults practically impossible."},{title:"Self-Sustaining Siege Garrison",icon:"💧",detail:"Equipped with large natural water reservoirs (Asha Devi Tank and Mama-Bhanja Pond) and massive granaries, defenders could survive multi-year sieges without surrendering for lack of food or water."}]},architecture:[{id:"jama-masjid",title:"Jama Masjid of Asirgarh",category:"Religious",icon:"🕌",image:"https://images.unsplash.com/photo-1590076175571-4b5459efb099?auto=format&fit=crop&w=800&q=80",description:"Built in 1588 CE by Adil Shah Faruqui, this magnificent stone mosque features twin 80-foot high minarets, elegant arches, and rare dual inscriptions in both Arabic calligraphy and Devanagari (Sanskrit)."},{id:"gupteshwar-temple",title:"Gupteshwar Shiva Temple",category:"Religious",icon:"🕉️",image:"https://images.unsplash.com/photo-1609766857041-ed402ea8069a?auto=format&fit=crop&w=800&q=80",description:"An ancient subterranean rock temple dedicated to Lord Shiva. According to enduring local folklore, Ashwatthama from the Mahabharata visits this temple every morning to offer fresh flowers."},{id:"triple-citadels",title:"Triple Fortress Complex",category:"Fortifications",icon:"🏰",image:"https://images.unsplash.com/photo-1599661046289-e31897846e41?auto=format&fit=crop&w=800&q=80",description:"The fort comprises three concentric hill defensive rings: Asirgarh (main upper citadel), Kamargarh (middle ridge defense), and Malaygarh (outer lower fortification)."},{id:"asha-devi-tank",title:"Asha Devi & Mama-Bhanja Water Tanks",category:"Water Systems",icon:"💧",image:"https://images.unsplash.com/photo-1584551246679-0daf3d275d0f?auto=format&fit=crop&w=800&q=80",description:"Massive natural rock-cut reservoirs that collected rainwater off the plateau. They provided perennial water to garrison troops even during peak summer blockades."},{id:"moti-mahal",title:"Moti Mahal & Palatial Ruins",category:"Palaces",icon:"🏛️",image:"https://images.unsplash.com/photo-1548013146-72479768bada?auto=format&fit=crop&w=800&q=80",description:"Royal residential quarters constructed during Mughal and Maratha rule, featuring arched corridors, zenana courtyards, and panoramic vantage points over the Satpuras."},{id:"phuta-darwaza",title:"Phuta Darwaza & Bastions",category:"Fortifications",icon:"🚪",image:"https://images.unsplash.com/photo-1590486803833-1c5dc8ddd4c8?auto=format&fit=crop&w=800&q=80",description:"The formidable entry gates featuring curved approach ramps, heavy wooden spiked doors, arrow slits, and cannon embrasures designed to annihilate advancing enemy cavalry."}],battles:[{title:"The Great Siege of Asirgarh (1600–1601 CE)",combatants:"Mughal Empire (Akbar) vs. Faruqui Dynasty (Bahadur Shah)",duration:"7 Months (August 1600 – January 1601)",result:"Mughal Victory via Negotiation & Gold Diplomacy",summary:"Emperor Akbar personally commanded over 50,000 troops and heavy artillery. However, Asirgarh's steep cliffs and 10-year grain stockpiles made direct military assault impossible. Akbar ultimately secured victory through diplomatic bribes to key Faruqui commanders and a plague outbreak inside the fort.",keyTakeaway:"This siege was Emperor Akbar's final military campaign before his death in 1605."},{title:"The Battle of Asirgarh (1819 CE)",combatants:"British East India Company vs. Scindia Maratha Garrison",duration:"20 Days (March 18 – April 9, 1819)",result:"British Victory & Annexation",summary:"During the closing phase of the Third Anglo-Maratha War, British forces under Brigadier-General John Doveton and Sir John Malcolm surrounded Asirgarh. Jaswant Rao Rambhau defended the fort valiantly under heavy siege mortar fire until ammunition ran low, after which the garrison surrendered with military honors.",keyTakeaway:"Marked the final fall of Maratha hill fortresses in Central India to British rule."}],facts:[{title:"Legend of Ashwatthama",category:"Folklore",icon:"✨",description:"Local tradition believes Ashwatthama, cursed with immortality in the Mahabharata, still roams Asirgarh and leaves fresh yellow marigold flowers on the Shiva Lingam at Gupteshwar temple every morning before sunrise."},{title:"Akbar's Golden Keys",category:"History",icon:"🔑",description:"Upon conquering Asirgarh in 1601, Emperor Akbar was so proud of capturing the 'unconquerable' fortress that he ordered golden and silver keys to be minted as symbols of unlocking the Deccan."},{title:"Akbar's Final Conquest",category:"History",icon:"🏆",description:"Asirgarh Fort was the last military fortress conquered by Mughal Emperor Akbar during his 49-year rule. Shortly after returning to Agra, his health declined and he passed away in 1605."},{title:"Sanskrit & Arabic Mosque Inscriptions",category:"Architecture",icon:"📜",description:"The Jama Masjid inside Asirgarh contains rare dual inscriptions written in both Arabic script and Sanskrit (Devanagari), reflecting the harmonious synthesis of Central Indian architecture."},{title:"Three Fortresses in One",category:"Military",icon:"🛡️",description:"Asirgarh is actually a complex of three separate fortified hills—Asirgarh (upper main citadel), Kamargarh (middle ridge), and Malaygarh (outer lower fort)."},{title:"Perennial Basalt Aquifers",category:"Engineering",icon:"💧",description:"Natural volcanic basalt formations on the plateau naturally trapped rainwater, creating deep springs that supplied clean drinking water even during multi-year sieges."}],gallery:[{title:"Asirgarh Fort Ramparts & Satpura Range",caption:"Panoramic view of Asirgarh Fort's massive basalt wall perched on the edge of the Satpura cliff.",image:"https://images.unsplash.com/photo-1599661046289-e31897846e41?auto=format&fit=crop&w=1200&q=80",category:"Landscape"},{title:"Jama Masjid of Asirgarh",caption:"The magnificent 16th-century Jama Masjid built by Adil Shah Faruqui with twin 80ft minarets.",image:"https://images.unsplash.com/photo-1590076175571-4b5459efb099?auto=format&fit=crop&w=1200&q=80",category:"Architecture"},{title:"Ancient Rock-Cut Water Tank",caption:"One of the deep rainwater reservoirs (Asha Devi Tank) that sustained the fort's garrison for months.",image:"https://images.unsplash.com/photo-1584551246679-0daf3d275d0f?auto=format&fit=crop&w=1200&q=80",category:"Engineering"},{title:"Gupteshwar Shiva Temple Ruins",caption:"The ancient rock temple associated with the legend of Ashwatthama inside the upper fort.",image:"https://images.unsplash.com/photo-1609766857041-ed402ea8069a?auto=format&fit=crop&w=1200&q=80",category:"Religious"},{title:"Fortified Gateway & Arched Ramp",caption:"The steep stone paved entrance path passing under heavy arched gatehouses and gun embrasures.",image:"https://images.unsplash.com/photo-1590486803833-1c5dc8ddd4c8?auto=format&fit=crop&w=1200&q=80",category:"Fortifications"},{title:"Moti Mahal Royal Residence Ruins",caption:"Arched halls and stone corridors of Moti Mahal inside the main citadel grounds.",image:"https://images.unsplash.com/photo-1548013146-72479768bada?auto=format&fit=crop&w=1200&q=80",category:"Heritage"}],quizQuestions:[{question:"Why was Asirgarh Fort known as the 'Gateway to the Deccan'?",options:["It was located on the coast of the Arabian Sea","It commanded the Burhanpur Gap, the main land route between North & South India","It had the highest mountain peak in South India","It was the capital of the Vijayanagara Empire"],correct:1,explanation:"Asirgarh sat directly above the Burhanpur Gap in the Satpura Range, controlling the only easy land pass between Northern India and the Deccan Plateau."},{question:"Who was the initial builder of the first fort on Asirgarh hill?",options:["Chhatrapati Shivaji Maharaj","Emperor Akbar","Asa Ahir, a local Ahir chieftain","British General Malcolm"],correct:2,explanation:"Asa Ahir, a wealthy chieftain of the Ahir community, constructed the original earthen fort in the 14th century to protect his cattle and people."},{question:"What historic event associated with Emperor Akbar occurred at Asirgarh in 1601 CE?",options:["He was crowned Emperor here","It was his final military conquest before his death in 1605","He signed the Treaty of Salbai here","He constructed the Taj Mahal here"],correct:1,explanation:"The 7-month Siege of Asirgarh (1600–1601 CE) was Emperor Akbar's final military campaign during his 49-year reign."},{question:"According to popular local folklore, which immortal warrior from the Mahabharata visits the Shiva temple inside Asirgarh every morning?",options:["Arjuna","Karna","Ashwatthama","Bheeshma"],correct:2,explanation:"Local tradition holds that Ashwatthama, who was granted immortality, still offers fresh flowers every morning at the Gupteshwar Shiva temple."},{question:"What is unique about the inscriptions inside the Jama Masjid of Asirgarh?",options:["They are written in Latin and Greek","They are dual inscriptions written in both Arabic and Sanskrit (Devanagari)","They are carved in silver leaf","They describe the construction of the Great Wall of China"],correct:1,explanation:"The Jama Masjid built by Adil Shah Faruqui in 1588 CE features rare dual inscriptions in both Arabic calligraphy and Sanskrit."}]};